use tree_sitter::Parser;
fn dump(node: tree_sitter::Node, src: &str, depth: usize) {
    let indent = "  ".repeat(depth);
    let text = &src[node.start_byte()..node.end_byte()];
    let t = text.replace('
', "\n");
    let named = if node.is_named() { "" } else { " (anon)" };
    let is_error = if node.is_error() || node.is_missing() { " <-- ERR/MISS" } else { "" };
    let truncated = if t.len() > 44 { format!("{}...", &t[..44]) } else { t };
    println!("{indent}{} {:?}{}{}", node.kind(), truncated, named, is_error);
    let mut cursor = node.walk();
    for child in node.children(&mut cursor) { dump(child, src, depth + 1); }
}
fn main() {
    let samples = vec![
        // superclass constructor call
        "classdef Foo < Bar
  methods
    function obj = Foo()
      obj = obj@Bar(1);
    end
  end
end
",
        // superclass constructor call, multi output
        "classdef Foo < Bar
  methods
    function [obj, x] = Foo()
      [obj, x] = obj@Bar(1);
    end
  end
end
",
        // superclass method call
        "classdef Foo < Bar
  methods
    function obj = Foo()
      obj = obj@Bar(1);
    end
    function y = mymethod(obj)
      y = mymethod@Bar(obj);
    end
  end
end
",
        // attributes on class
        "classdef (Sealed, Abstract) Foo
  methods
  end
end
",
        // attributes on methods/properties blocks
        "classdef Foo
  properties (Constant, Abstract)
    x
  end
  methods (Access = private, Abstract)
    function y = f(obj)
    end
  end
end
",
        // duplicate attribute
        "classdef (Sealed, Sealed) Foo
  methods
  end
end
",
        // weak handle
        "classdef Foo
  properties (WeakHandle, Constant)
    x
  end
  properties (WeakHandle, Dependent)
    y
  end
  properties (WeakHandle)
    z
  end
end
",
        // property default value referencing class itself
        "classdef Foo
  properties
    x Foo = Foo()
  end
end
",
        // assignment to constant prop
        "classdef Foo
  properties (Constant)
    x = 5
  end
  methods
    function obj = Foo()
      obj.x = 6;
    end
    function f(obj)
      obj.x = 7;
    end
  end
end
",
        // Access + SetAccess together
        "classdef Foo
  properties (Access = private, SetAccess = private)
    x
  end
end
",
        // AllowedSubclasses
        "classdef (Sealed, AllowedSubclasses = ?Foo) Foo
  methods
  end
end
",
        // setter/getter abstract
        "classdef Foo
  properties
    x
  end
  methods
    function set.x(obj, val)
    end
    function val = get.x(obj)
    end
  end
end
",
        // TestParameterDefinition
        "classdef Foo
  methods (Static)
    function params = TestParameterDefinition()
    end
  end
  methods
    function params = TestParameterDefinition()
    end
  end
end
",
        // many inputs/outputs
        "function [a1,a2,a3,a4,a5,a6,a7,a8,a9,a10,a11,a12,a13,a14,a15,a16,a17,a18,a19,a20,a21,a22,a23,a24,a25,a26,a27,a28,a29,a30,a31,a32,a33,a34,a35,a36,a37,a38,a39,a40,a41,a42,a43,a44,a45,a46,a47,a48,a49,a50,a51,a52,a53,a54,a55,a56,a57,a58,a59,a60,a61,a62,a63,a64,a65] = f(b1,b2,b3,b4,b5,b6,b7,b8,b9,b10,b11,b12,b13,b14,b15,b16,b17,b18,b19,b20,b21,b22,b23,b24,b25,b26,b27,b28,b29,b30,b31,b32,b33,b34,b35,b36,b37,b38,b39,b40,b41,b42,b43,b44,b45,b46,b47,b48,b49,b50,b51,b52,b53,b54,b55,b56,b57,b58,b59,b60,b61,b62,b63,b64,b65)
end
",
        // conditional superclass call
        "classdef Foo < Bar
  methods
    function obj = Foo(x)
      if x > 0
        obj = obj@Bar(1);
      end
    end
  end
end
",
        // object use before super call
        "classdef Foo < Bar
  properties
    y
  end
  methods
    function obj = Foo()
      obj.y = 1;
      obj = obj@Bar();
    end
  end
end
",
    ];
    let mut parser = Parser::new();
    parser.set_language(&tree_sitter_matlab::LANGUAGE.into()).unwrap();
    for (i, s) in samples.iter().enumerate() {
        let tree = parser.parse(s, None).unwrap();
        println!("===== {i}: {s:?} =====");
        dump(tree.root_node(), s, 0);
        println!();
    }
}

